"use strict";(self.webpackChunkmindstack=self.webpackChunkmindstack||[]).push([["1641"],{1897(e,a,n){n.r(a),n.d(a,{metadata:()=>t,default:()=>h,frontMatter:()=>r,contentTitle:()=>l,toc:()=>c,assets:()=>o});var t=JSON.parse('{"id":"SoftwareEngineering/scalability-patterns","title":"Scalability Patterns","description":"How systems grow to handle more load \u2014 more users, more data, more requests per second \u2014 without falling over. This page covers the core techniques and, just as importantly, when each one is actually needed.","source":"@site/docs/SoftwareEngineering/16-scalability-patterns.md","sourceDirName":"SoftwareEngineering","slug":"/SoftwareEngineering/scalability-patterns","permalink":"/Mindstack/docs/SoftwareEngineering/scalability-patterns","draft":false,"unlisted":false,"tags":[],"version":"current","sidebarPosition":16,"frontMatter":{"title":"Scalability Patterns","sidebar_label":"Scalability Patterns","sidebar_position":16},"sidebar":"softwareEngineeringSidebar","previous":{"title":"Caching Strategies","permalink":"/Mindstack/docs/SoftwareEngineering/caching-strategies"},"next":{"title":"Consistency & CAP Theorem","permalink":"/Mindstack/docs/SoftwareEngineering/consistency-cap-theorem"}}'),s=n(4848),i=n(8453);let r={title:"Scalability Patterns",sidebar_label:"Scalability Patterns",sidebar_position:16},l="Scalability Patterns",o={},c=[{value:"Vertical vs Horizontal Scaling",id:"vertical-vs-horizontal-scaling",level:2},{value:"Statelessness \u2014 The Prerequisite for Horizontal Scaling",id:"statelessness--the-prerequisite-for-horizontal-scaling",level:2},{value:"Load Balancing",id:"load-balancing",level:2},{value:"Database Scaling \u2014 Replication",id:"database-scaling--replication",level:2},{value:"Database Scaling \u2014 Sharding",id:"database-scaling--sharding",level:2},{value:"Scaling Patterns Beyond the Database",id:"scaling-patterns-beyond-the-database",level:2},{value:"Queue-Based Load Leveling",id:"queue-based-load-leveling",level:3},{value:"Read-Through Cache",id:"read-through-cache",level:3},{value:"CDN for Static Content",id:"cdn-for-static-content",level:3},{value:"Auto-Scaling",id:"auto-scaling",level:3},{value:"Scaling Anti-Patterns",id:"scaling-anti-patterns",level:2},{value:"Tips",id:"tips",level:2},{value:"Summary",id:"summary",level:2}];function d(e){let a={code:"code",h1:"h1",h2:"h2",h3:"h3",header:"header",hr:"hr",li:"li",p:"p",pre:"pre",ul:"ul",...(0,i.R)(),...e.components};return(0,s.jsxs)(s.Fragment,{children:[(0,s.jsx)(a.header,{children:(0,s.jsx)(a.h1,{id:"scalability-patterns",children:"Scalability Patterns"})}),"\n",(0,s.jsx)(a.p,{children:"How systems grow to handle more load \u2014 more users, more data, more requests per second \u2014 without falling over. This page covers the core techniques and, just as importantly, when each one is actually needed."}),"\n",(0,s.jsx)(a.hr,{}),"\n",(0,s.jsx)(a.h2,{id:"vertical-vs-horizontal-scaling",children:"Vertical vs Horizontal Scaling"}),"\n",(0,s.jsx)(a.pre,{children:(0,s.jsx)(a.code,{children:'VERTICAL SCALING ("scale up")\n  Make ONE machine more powerful \u2014 more CPU, more RAM, faster disk.\n\n    \u250C\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2510         \u250C\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2510\n    \u2502  2 CPU   \u2502   \u2500\u2500>   \u2502   16 CPU   \u2502\n    \u2502  4GB RAM \u2502         \u2502  64GB RAM  \u2502\n    \u2514\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2518         \u2514\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2518\n\n  Simple \u2014 usually no code changes required. Has a hard ceiling \u2014\n  eventually you run out of bigger machines to buy, and cost grows\n  faster than capacity at the high end.\n\nHORIZONTAL SCALING ("scale out")\n  Add MORE machines, and distribute load across all of them.\n\n    \u250C\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2510   \u250C\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2510   \u250C\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2510   \u250C\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2510\n    \u2502 Server 1 \u2502   \u2502 Server 2 \u2502   \u2502 Server 3 \u2502   \u2502 Server 4 \u2502\n    \u2514\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2518   \u2514\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2518   \u2514\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2518   \u2514\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2518\n\n  No hard ceiling in principle \u2014 keep adding machines. Requires the\n  application to actually SUPPORT running many instances at once\n  (see Statelessness, below) \u2014 this is real engineering work, not free.\n'})}),"\n",(0,s.jsx)(a.pre,{children:(0,s.jsx)(a.code,{children:"Practical guidance:\n  Vertical scaling first, for as long as it's simple and cost-effective \u2014\n  don't build horizontal-scaling complexity before you need it (YAGNI,\n  file 04). A single well-specified modern server handles a genuinely\n  large amount of traffic for many real applications.\n\n  Horizontal scaling once vertical scaling's ceiling or cost curve\n  becomes a real, demonstrated problem \u2014 and once the application is\n  actually designed to support it (stateless, as covered next).\n"})}),"\n",(0,s.jsx)(a.hr,{}),"\n",(0,s.jsx)(a.h2,{id:"statelessness--the-prerequisite-for-horizontal-scaling",children:"Statelessness \u2014 The Prerequisite for Horizontal Scaling"}),"\n",(0,s.jsx)(a.pre,{children:(0,s.jsx)(a.code,{children:"STATEFUL server (holds session data in local memory):\n\n   User's first request  \u2500\u2500\u25B6  Server A  (session stored in Server A's memory)\n   User's second request \u2500\u2500\u25B6  Server B  (Server B has NO idea who this user is!)\n\n  Horizontal scaling breaks immediately unless every request from\n  the same user is somehow always routed to the SAME server (called\n  \"sticky sessions\" \u2014 a workaround with its own problems: uneven load\n  distribution, and losing that server means losing every session it held).\n\nSTATELESS server (session data lives externally, not in server memory):\n\n   User's first request  \u2500\u2500\u25B6  Server A  \u2500\u2500\u25B6  reads/writes session in Redis\n   User's second request \u2500\u2500\u25B6  Server B  \u2500\u2500\u25B6  reads/writes the SAME session in Redis\n\n  ANY server can handle ANY request, because no server holds\n  request-specific state in its own local memory \u2014 it's all externalized\n  to a shared store (Redis, a database) that every instance can reach.\n"})}),"\n",(0,s.jsx)(a.pre,{children:(0,s.jsx)(a.code,{children:"Making an application stateless usually means:\n  Session data \u2192 external store (Redis, database) instead of\n  in-process memory\n  File uploads \u2192 object storage (S3-equivalent) instead of the local\n  filesystem of whichever server happened to handle that request\n  Background job state \u2192 a shared job queue/database, not an\n  in-memory queue local to one instance\n\nThis is a genuine, real design constraint you build FOR, not something\nthat happens automatically \u2014 an application built assuming a single\nlong-running process needs real changes to become horizontally scalable.\n"})}),"\n",(0,s.jsx)(a.hr,{}),"\n",(0,s.jsx)(a.h2,{id:"load-balancing",children:"Load Balancing"}),"\n",(0,s.jsx)(a.p,{children:"Distributes incoming requests across multiple server instances \u2014 the piece of infrastructure that actually makes horizontal scaling work in practice. Covered in full depth (algorithms, Layer 4 vs Layer 7, health checks) in the DevOps course's Nginx and Load Balancing page \u2014 the summary here is the application-design angle."}),"\n",(0,s.jsx)(a.pre,{children:(0,s.jsx)(a.code,{children:"                    Load Balancer\n                          \u2502\n          \u250C\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u253C\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2510\n          \u25BC               \u25BC               \u25BC\n     \u250C\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2510    \u250C\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2510    \u250C\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2510\n     \u2502 Server 1 \u2502    \u2502 Server 2 \u2502    \u2502 Server 3 \u2502\n     \u2514\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2518    \u2514\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2518    \u2514\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2518\n\nThe load balancer also provides FAILOVER \u2014 if Server 2 becomes\nunhealthy, the load balancer stops routing to it and distributes\nthat traffic across the remaining healthy instances automatically.\n"})}),"\n",(0,s.jsx)(a.hr,{}),"\n",(0,s.jsx)(a.h2,{id:"database-scaling--replication",children:"Database Scaling \u2014 Replication"}),"\n",(0,s.jsx)(a.p,{children:"Adding read replicas lets read traffic scale horizontally even when the underlying data model doesn't naturally shard."}),"\n",(0,s.jsx)(a.pre,{children:(0,s.jsx)(a.code,{children:"                     Writes only\n                          \u2502\n                          \u25BC\n                  \u250C\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2510\n                  \u2502  Primary (DB)  \u2502\n                  \u2514\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u252C\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2518\n                          \u2502  replicates changes\n              \u250C\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u253C\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2510\n              \u25BC           \u25BC           \u25BC\n        \u250C\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2510\u250C\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2510\u250C\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2510\n        \u2502 Replica 1\u2502\u2502 Replica 2\u2502\u2502 Replica 3\u2502  \u25C0\u2500\u2500 reads distributed\n        \u2514\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2518\u2514\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2518\u2514\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2518        across replicas\n"})}),"\n",(0,s.jsx)(a.pre,{children:(0,s.jsx)(a.code,{children:'Writes go to the primary; the primary replicates its changes to\nreplicas, which serve read traffic.\n\nTrade-off: replication is typically asynchronous, meaning replicas\nlag slightly behind the primary \u2014 a write to the primary might not\nbe visible on a replica for a brief window (milliseconds, usually,\nbut not instant). This is a form of eventual consistency (see file 17)\n\u2014 fine for most read traffic (a product listing page doesn\'t need\nto reflect a write from 50 milliseconds ago), but a problem if code\nimmediately reads its own just-written data from a replica and\nexpects to see it (a common real bug \u2014 "read-after-write" needs to\neither read from the primary, or use a replica confirmed to be caught up).\n'})}),"\n",(0,s.jsx)(a.hr,{}),"\n",(0,s.jsx)(a.h2,{id:"database-scaling--sharding",children:"Database Scaling \u2014 Sharding"}),"\n",(0,s.jsx)(a.p,{children:"Splits data across multiple databases, each holding a subset of the data \u2014 used when a single database's write capacity or total data size becomes the actual bottleneck (replication alone only scales READS, not writes)."}),"\n",(0,s.jsx)(a.pre,{children:(0,s.jsx)(a.code,{children:"        Shard by customer_id range\n\n   customer_id 1-1000000        customer_id 1000001-2000000\n          \u2502                              \u2502\n          \u25BC                              \u25BC\n    \u250C\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2510                  \u250C\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2510\n    \u2502  Shard A  \u2502                  \u2502  Shard B  \u2502\n    \u2514\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2518                  \u2514\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2518\n"})}),"\n",(0,s.jsx)(a.pre,{children:(0,s.jsx)(a.code,{children:'Sharding strategies:\n  Range-based (as above) \u2014 simple, but can create "hot shards" if\n  data/traffic isn\'t evenly distributed across the ranges\n  Hash-based \u2014 hash the shard key (e.g. customer_id) to distribute\n  more evenly, at the cost of losing simple range queries across shards\n  Directory-based \u2014 a lookup service maps each key to its shard,\n  most flexible, but the lookup service itself becomes critical\n  infrastructure needing its own reliability\n\nReal cost of sharding: queries spanning multiple shards (e.g. "top 10\ncustomers across the entire system") become genuinely hard \u2014 no\nsingle database can answer that with a simple query anymore; it\nrequires querying every shard and combining results in application\ncode, or maintaining a separate aggregated read model (see CQRS, file 12).\n\nSharding is a significant architectural commitment \u2014 reach for it\nonly once replication and vertical scaling of the primary genuinely\ncan\'t keep up, not preemptively.\n'})}),"\n",(0,s.jsx)(a.hr,{}),"\n",(0,s.jsx)(a.h2,{id:"scaling-patterns-beyond-the-database",children:"Scaling Patterns Beyond the Database"}),"\n",(0,s.jsx)(a.h3,{id:"queue-based-load-leveling",children:"Queue-Based Load Leveling"}),"\n",(0,s.jsx)(a.p,{children:"Absorbs traffic spikes by decoupling the rate work arrives from the rate it's processed \u2014 directly connects to the message queue concepts in file 12."}),"\n",(0,s.jsx)(a.pre,{children:(0,s.jsx)(a.code,{children:"   Traffic spike:           Without a queue:          With a queue:\n   1000 req/sec instantly   All 1000 hit the           1000 queued;\n                             database at once,           workers process\n                             risking overload             at a sustainable,\n                                                            steady rate\n"})}),"\n",(0,s.jsx)(a.h3,{id:"read-through-cache",children:"Read-Through Cache"}),"\n",(0,s.jsx)(a.p,{children:"Reduces database load for hot data by serving repeated reads from a cache instead \u2014 covered in full depth in file 15, Caching Strategies."}),"\n",(0,s.jsx)(a.h3,{id:"cdn-for-static-content",children:"CDN for Static Content"}),"\n",(0,s.jsx)(a.p,{children:"Offloads static asset serving to edge servers geographically close to users, so the origin servers only handle dynamic requests \u2014 covered in file 15."}),"\n",(0,s.jsx)(a.h3,{id:"auto-scaling",children:"Auto-Scaling"}),"\n",(0,s.jsx)(a.p,{children:"Automatically adjusts the NUMBER of running instances based on real-time load, rather than provisioning for peak capacity permanently (wasteful) or average capacity permanently (fails under spikes). Covered in depth in the DevOps course's Kubernetes storage-and-scaling page (Horizontal Pod Autoscaler) and AWS fundamentals page (Auto Scaling Groups)."}),"\n",(0,s.jsx)(a.hr,{}),"\n",(0,s.jsx)(a.h2,{id:"scaling-anti-patterns",children:"Scaling Anti-Patterns"}),"\n",(0,s.jsx)(a.pre,{children:(0,s.jsx)(a.code,{children:'Scaling prematurely (see file 24, Anti-Patterns):\n  Building sharding, multi-region deployment, and complex caching\n  layers for an application with a few hundred users. This is the\n  data/infrastructure equivalent of premature abstraction \u2014 real\n  cost paid today for a capacity need that may never actually arrive.\n\nIgnoring the actual bottleneck:\n  Adding more application servers (horizontal scaling) when the REAL\n  bottleneck is the single database they all share \u2014 this doesn\'t\n  help; the database was already the constraint, and now MORE\n  application servers are hammering it harder. Profile and identify\n  the actual bottleneck before scaling anything (see file 20,\n  Technical Debt, and file 24 for the broader "measure before you\n  optimize" principle).\n\nTreating all data the same:\n  Not every table/entity needs the same scaling treatment. A\n  `product_catalog` table (read-heavy, changes rarely) benefits\n  enormously from caching and read replicas. A `payment_transactions`\n  table (needs strict consistency, moderate volume) may not want\n  the same eventual-consistency trade-offs at all. Scale the specific\n  parts of the system that actually need it, informed by real\n  measurement \u2014 not uniformly across everything.\n'})}),"\n",(0,s.jsx)(a.hr,{}),"\n",(0,s.jsx)(a.h2,{id:"tips",children:"Tips"}),"\n",(0,s.jsxs)(a.ul,{children:["\n",(0,s.jsx)(a.li,{children:"Scale vertically first, for as long as it remains simple and cost-effective \u2014 don't build horizontal-scaling complexity before a real, measured need arrives."}),"\n",(0,s.jsx)(a.li,{children:"Design for statelessness from the start, even before you need to scale horizontally \u2014 retrofitting statelessness onto an application built assuming a single process is real, disruptive work."}),"\n",(0,s.jsx)(a.li,{children:"Read replicas scale reads; sharding is required to scale writes and total data volume beyond one primary database's capacity \u2014 know which problem you actually have before reaching for either."}),"\n",(0,s.jsx)(a.li,{children:"Always identify the ACTUAL bottleneck (via real profiling/measurement) before scaling anything \u2014 adding more of the wrong resource doesn't help, and can even make things worse by increasing pressure on the true bottleneck."}),"\n",(0,s.jsx)(a.li,{children:"Different parts of your system likely have different scaling needs \u2014 apply caching, replication, sharding, and auto-scaling to the specific components that actually need them, not uniformly across the whole system."}),"\n"]}),"\n",(0,s.jsx)(a.hr,{}),"\n",(0,s.jsx)(a.h2,{id:"summary",children:"Summary"}),"\n",(0,s.jsxs)(a.ul,{children:["\n",(0,s.jsx)(a.li,{children:"Vertical scaling (bigger machine) is simpler and has a real, useful ceiling; horizontal scaling (more machines) has no inherent ceiling but requires the application to actually support running many instances \u2014 start vertical, move horizontal when genuinely needed."}),"\n",(0,s.jsx)(a.li,{children:"Statelessness (session data and file storage externalized, not held in server memory) is the prerequisite that makes horizontal scaling and load balancing actually work."}),"\n",(0,s.jsx)(a.li,{children:"Read replicas scale read capacity with some replication lag (eventual consistency); sharding scales write capacity and total data size, at real query-complexity cost for cross-shard operations."}),"\n",(0,s.jsx)(a.li,{children:"Queue-based load leveling, caching, CDNs, and auto-scaling each address a different specific bottleneck \u2014 apply the one that matches your actual, measured problem."}),"\n",(0,s.jsx)(a.li,{children:"Scaling prematurely, or scaling the wrong component instead of the actual bottleneck, are the two most common real-world scaling mistakes \u2014 measure first, then scale precisely what needs it."}),"\n"]})]})}function h(e={}){let{wrapper:a}={...(0,i.R)(),...e.components};return a?(0,s.jsx)(a,{...e,children:(0,s.jsx)(d,{...e})}):d(e)}},8453(e,a,n){n.d(a,{R:()=>r,x:()=>l});var t=n(6540);let s={},i=t.createContext(s);function r(e){let a=t.useContext(i);return t.useMemo(function(){return"function"==typeof e?e(a):{...a,...e}},[a,e])}function l(e){let a;return a=e.disableParentContext?"function"==typeof e.components?e.components(s):e.components||s:r(e.components),t.createElement(i.Provider,{value:a},e.children)}}}]);